insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_125'
from (values
('127.872.d.1.A',3,'A student arranges to run a small inventory-counting project at a distribution center: she sets goals, schedules her weeks, completes the counts and reviews how it went. She is:','["planning, conducting and evaluating an industry-based occupational experience", "only watching others", "skipping the review", "doing the work at random"]'::jsonb,0,'A supervised experience follows plan, do, evaluate.','original'),
('127.872.d.1.A',4,'A written proposal for a supervised warehouse project should be reviewed and approved by:','["the delivery driver", "the teacher and the work-site supervisor before work begins", "no one", "only classmates"]'::jsonb,1,'Approval keeps the project aligned.','original'),
('127.872.d.1.B',3,'A student writes down each pallet count, the shift and the supervisor''s initials on a daily log for her warehouse project. She is applying:','["random notes", "storage tricks", "proper record-keeping skills", "guessing skills"]'::jsonb,2,'Daily logs document work.','original'),
('127.872.d.1.B',4,'Which entry makes the best record of a logistics learning activity?','["only the weather", "no date", "only a smiley face", "date, hours, task performed, result and supervisor signature"]'::jsonb,3,'Complete records include key facts.','original'),
('127.872.d.1.C',3,'A student sets up a tracker with tabs for orders picked, errors found and hours worked for her warehouse job. She is:','["using a customized record-keeping system for her industry experience", "copying a template unchanged", "using a generic note only", "using no system"]'::jsonb,0,'Custom systems track what matters.','original'),
('127.872.d.1.C',4,'A record system for an order-picking project is most helpful if it:','["is never opened", "tracks accuracy and speed over time", "has no dates", "tracks unrelated hobbies"]'::jsonb,1,'Track measures that show progress.','original'),
('127.872.d.1.D',3,'A student runs a food-drive collection with her logistics club and coordinates volunteers to sort and ship the boxes. This is an example of:','["a payroll task", "a vehicle repair", "a youth leadership opportunity", "a customs fine"]'::jsonb,2,'Leading a project builds leadership.','original'),
('127.872.d.1.D',4,'How does serving as a team captain for a student supply-chain contest help a student''s work experience?','["it avoids responsibility", "it limits growth", "it replaces the work", "it builds communication, planning and leadership skills"]'::jsonb,3,'Roles build skills.','original'),
('127.872.d.1.E',3,'Before starting a job-shadowing project, a student lists the weekly tasks, the supplies she needs and the costs of transportation. She is developing:','["a work plan and budget", "a travel photo album", "a floor plan", "a menu"]'::jsonb,0,'Plans include tasks and costs.','original'),
('127.872.d.1.E',4,'If a project''s expected expenses are $120 and the student has $90, the budget shows:','["a $30 surplus", "a $30 shortfall that needs a plan", "a $210 total income", "no difference"]'::jsonb,1,'120 − 90 = 30.','original'),
('127.872.d.2.A',3,'A student notices that some countries use pallets of different standard sizes than the United States. This is a:','["mistake in measurement", "rule for pilots", "difference in international practices in distribution", "similarity in every nation"]'::jsonb,2,'Standards differ internationally.','original'),
('127.872.d.2.A',4,'A similarity between warehouses in different nations is that most:','["avoid shipping", "sell directly to customers only", "use no systems", "store goods, track inventory and move orders out"]'::jsonb,3,'Basic functions are shared.','original'),
('127.872.d.2.B',3,'A distributor sells medical gloves to Canada, auto parts to Mexico and grain to Egypt. This shows:','["the variety of world markets", "no demand", "limited trade", "only a local market"]'::jsonb,0,'Different markets want different goods.','original'),
('127.872.d.2.B',4,'Before expanding a delivery service overseas, a company should study the:','["color of the trucks", "needs, rules and income levels of the new market", "menu of a café", "name of the mayor only"]'::jsonb,1,'Research the market first.','original'),
('127.872.d.2.C',3,'A logistics manager learns that package labels must be translated and that one country''s customers prefer cash on delivery. These are:','["office supplies", "road hazards", "marketing factors and practices that affect other cultures", "engine repairs"]'::jsonb,2,'Local practices shape marketing.','original'),
('127.872.d.2.C',4,'A brand name that sounds fine in English but has a negative meaning abroad shows why companies must:','["avoid labels", "use the same ad everywhere", "skip testing", "research language and culture before marketing"]'::jsonb,3,'Cultural research prevents blunders.','original'),
('127.872.d.3.A',3,'A new warehouse hire learns that ''SKU'' is a unique code for each product and ''cross-docking'' means moving goods straight from inbound to outbound trucks. She is:','["learning terms used in distribution and logistics", "skipping orientation", "guessing words", "avoiding vocabulary"]'::jsonb,0,'Know the terms.','original'),
('127.872.d.3.A',4,'In logistics, ''lead time'' is:','["a forklift attachment", "the time between placing an order and receiving it", "a type of truck", "the length of a pallet"]'::jsonb,1,'Lead time measures order-to-receipt delay.','original'),
('127.872.d.3.B',3,'Online orders reach homes in two days because of fulfillment centers and delivery networks. This shows the:','["absence of trade", "small impact", "scope and effect of distribution and logistics on society", "limited role of logistics"]'::jsonb,2,'Logistics shapes daily life.','original'),
('127.872.d.3.B',4,'If a regional distribution center shut down unexpectedly, nearby stores would most likely:','["have no change", "lower all prices", "receive extra stock", "run short of stock and lose sales"]'::jsonb,3,'Supply chain disruptions cause shortages.','original'),
('127.872.d.3.C',3,'The adoption of barcodes, containerization and online order tracking are examples of:','["significant historical and current developments in logistics", "unrelated hobbies", "minor changes", "fictional ideas"]'::jsonb,0,'Technology reshaped logistics.','original'),
('127.872.d.3.C',4,'Which current development lets customers see a package''s location in real time?','["a paper map only", "GPS and scan-based tracking", "a handwritten ledger", "a rotary phone"]'::jsonb,1,'Tracking uses scans and GPS.','original'),
('127.872.d.3.D',3,'Engineers testing warehouse robots that pick and sort items and delivery drones are exploring:','["unrelated sports", "old methods", "possible future scenarios for distribution and logistics", "historical events"]'::jsonb,2,'Prototypes hint at the future.','original'),
('127.872.d.3.D',4,'A likely future scenario in large fulfillment centers is:','["a return to paper only", "no technology", "fewer products", "more automation with robots working alongside people"]'::jsonb,3,'Automation is expanding.','original'),
('127.872.d.3.E',3,'A retailer uses artificial intelligence to forecast demand and ships goods from overseas factories on tight schedules. This shows how:','["emerging technologies and globalization affect distribution", "globalization lowers trade", "forecasts slow orders", "technology has no role"]'::jsonb,0,'Technology and global trade work together.','original'),
('127.872.d.3.E',4,'Global supply chains make companies more vulnerable to:','["local weather only", "disruptions at faraway ports or suppliers", "nothing at all", "local holidays only"]'::jsonb,1,'Long chains have more risk points.','original'),
('127.872.d.3.F',3,'A company weighs paying more for faster air freight against cheaper but slower ocean shipping. This is comparing:','["only uniforms", "only holidays", "issues affecting logistics such as cost, speed and reliability", "only colors"]'::jsonb,2,'Trade-offs shape shipping choices.','original'),
('127.872.d.3.F',4,'A big factor driving up the cost of last-mile delivery in cities is:','["short routes", "low fuel use", "empty roads", "traffic congestion and failed delivery attempts"]'::jsonb,3,'Last-mile costs are high.','original'),
('127.872.d.4.A',3,'A warehouse manager forecasts demand, assigns staff, tracks budgets and checks results against targets. These are:','["common business management principles", "personal chores", "random acts", "hobbies"]'::jsonb,0,'Plan, organize, lead, control.','original'),
('127.872.d.4.A',4,'A manager who compares shipping errors against the goal and fixes the process is using the function of:','["avoiding", "controlling", "guessing", "delaying"]'::jsonb,1,'Controlling compares results to goals.','original'),
('127.872.d.4.B',3,'A forklift operator signs up for a supervisor-in-training course and mentors new hires. She is:','["ignoring training", "quitting", "taking an opportunity for leadership development and personal growth", "avoiding promotion"]'::jsonb,2,'Training builds leaders.','original'),
('127.872.d.4.B',4,'Which activity best develops leadership in a distribution career?','["working in silence", "avoiding feedback", "skipping meetings", "leading a safety huddle at the start of a shift"]'::jsonb,3,'Leading huddles builds leadership.','original'),
('127.872.d.4.C',3,'A student council chair posts an agenda, recognizes speakers and calls for a vote on each motion. She is demonstrating:','["democratic principles in conducting an effective meeting", "avoiding discussion", "unfair control", "random talk"]'::jsonb,0,'Fair procedures.','original'),
('127.872.d.4.C',4,'Which job belongs to the secretary at a formal meeting?','["running the vote count only", "recording the minutes of what was decided", "setting the agenda alone", "owning the gavel"]'::jsonb,1,'The secretary keeps minutes.','original'),
('127.872.d.4.D',3,'A shift team of pickers, packers and loaders handles a holiday rush with clear roles and open communication. This shows strong:','["competition only", "isolation", "team dynamics", "confusion"]'::jsonb,2,'Healthy teams share roles and communicate.','original'),
('127.872.d.4.D',4,'One stage that a new team often goes through as members test roles and ideas is called:','["sleeping", "ending", "hiding", "storming"]'::jsonb,3,'Tuckman''s storming stage.','original'),
('127.872.d.4.E',3,'A logistics company says it aims to deliver every order accurately and on time and sets a goal of 99 percent order accuracy. This is:','["developing an organizational vision, mission and goals", "a random statement", "ignoring customers", "setting no direction"]'::jsonb,0,'Goals follow from the mission.','original'),
('127.872.d.4.E',4,'A measurable organizational goal is:','["improve someday", "reduce average order processing time from 48 hours to 36 hours this year", "work hard", "be better"]'::jsonb,1,'Measurable goals include numbers and a time.','original'),
('127.872.d.5.A',3,'A warehouse in Laredo handles shipments between Texas and Mexico because each side makes goods the other wants at lower cost. This explains a reason for:','["price fixing", "isolation", "world trade and globalization", "trade bans"]'::jsonb,2,'Trade rewards specialization.','original'),
('127.872.d.5.A',4,'Which factor most encourages two countries to trade electronics and produce?','["identical economies", "no ports", "no demand", "each produces something the other values more cheaply"]'::jsonb,3,'Comparative advantage.','original'),
('127.872.d.5.B',3,'Lawmakers debate whether to fund a new inland port, and local businesses and residents argue over the plan. This shows the:','["political impact of distribution and logistics", "random events", "lack of interest", "absence of politics"]'::jsonb,0,'Logistics projects involve politics.','original'),
('127.872.d.5.B',4,'Tariffs on imported goods affect logistics companies because they:','["end shipping", "change shipping volumes and costs", "remove all risk", "make trucks faster"]'::jsonb,1,'Trade policy affects flows.','original'),
('127.872.d.5.C',3,'A distribution center reviews customs and hazardous-materials shipping rules and updates its labeling procedures. This is:','["ignoring updates", "avoiding laws", "reviewing regulations and laws to evaluate their impact on operations", "skipping training"]'::jsonb,2,'Stay compliant.','original'),
('127.872.d.5.C',4,'Failing to follow hazardous-materials shipping rules could lead a company to face:','["higher bonuses", "no consequence", "lower insurance", "fines, accidents and loss of shipping privileges"]'::jsonb,3,'Noncompliance has penalties.','original'),
('127.872.d.5.D',3,'A logistics supervisor reads a supply chain newsletter each week to track port delays and fuel trends. This shows:','["reading written material to stay abreast of current issues", "avoiding news", "ignoring trends", "skipping reading"]'::jsonb,0,'Stay informed.','original'),
('127.872.d.5.D',4,'Reading industry reports can help a distribution manager to:','["ignore customers", "anticipate changes that affect inventory and routes", "skip training", "avoid forecasts"]'::jsonb,1,'Awareness supports planning.','original'),
('127.872.d.5.E',3,'A distribution company polls its retail customers about delivery times and tallies late-order complaints before changing routes. It is:','["guessing", "avoiding data", "collecting public opinion and data to make informed decisions", "ignoring customers"]'::jsonb,2,'Gather feedback and data.','original'),
('127.872.d.5.E',4,'The strongest basis for deciding to add a second shift is:','["a hunch", "a rumor", "a single opinion", "order backlog data and customer lead-time surveys"]'::jsonb,3,'Data supports decisions.','original'),
('127.872.d.5.F',3,'A logistics planner lists three warehouse sites, compares the cost, travel time and storage capacity of each, and recommends one. She is using:','["critical-thinking skills to identify and organize alternatives", "random picks", "copying competitors", "avoiding options"]'::jsonb,0,'Compare alternatives.','original'),
('127.872.d.5.F',4,'After listing alternatives for reducing late deliveries, the next step is to:','["stop planning", "weigh each option against cost, time and risk", "choose the first one", "ignore costs"]'::jsonb,1,'Evaluate each option.','original'),
('127.872.d.5.G',3,'A retailer checks whether its third-party carrier delivered 97 percent of orders on time as agreed in the contract. This is:','["paying blindly", "avoiding records", "evaluating performance and contract compliance of service providers", "ignoring the contract"]'::jsonb,2,'Review providers against agreements.','original'),
('127.872.d.5.G',4,'If a carrier repeatedly damages goods in transit despite contract terms, the company should:','["ignore it", "hide the claims", "pay a bonus", "document the damage and enforce or renegotiate the contract"]'::jsonb,3,'Hold providers accountable.','original'),
('127.872.d.6.A',3,'A shipping clerk is told to change the weight on a form to lower the freight charge. She refuses because it would be dishonest and illegal. She is examining:','["workplace ethical and legal responsibilities", "pay rates", "dress codes", "break times"]'::jsonb,0,'Honesty and law guide conduct.','original'),
('127.872.d.6.A',4,'Which behavior best reflects ethical responsibility for someone who handles customer shipments?','["blaming a customer", "reporting a damaged or missing item truthfully", "hiding the damage", "skipping the report"]'::jsonb,1,'Honesty protects trust.','original'),
('127.872.d.6.B',3,'A customer service rep thanks callers, uses names politely and waits for them to finish speaking. She is using:','["slang only", "interruptions", "proper etiquette", "rude habits"]'::jsonb,2,'Courtesy matters.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_125'
from (values
('127.872.d.6.B',4,'Good etiquette when emailing a client about a delayed shipment includes:','["no greeting", "insults", "all capital letters", "a clear subject line, polite tone and proposed next steps"]'::jsonb,3,'Professional email etiquette.','original'),
('127.872.d.6.C',3,'A warehouse associate arrives with clean clothes, closed-toe shoes and enough sleep before a long shift. This shows:','["appropriate personal appearance and health habits", "careless dress", "ignoring rest", "poor grooming"]'::jsonb,0,'Appearance and health habits matter.','original'),
('127.872.d.6.C',4,'Staying hydrated and taking scheduled breaks helps a warehouse worker by:','["raising injury risk", "keeping energy and focus high while lifting and moving goods", "increasing errors", "slowing workflow only"]'::jsonb,1,'Health supports safety.','original'),
('127.872.d.6.D',3,'A dispatcher writes a short email to a carrier about a changed pickup time and then calls the driver to confirm. She is practicing:','["silence only", "avoidance", "written and oral communication in formal and informal situations", "confusion"]'::jsonb,2,'Combine writing and talking.','original'),
('127.872.d.6.D',4,'A message to a carrier about a late pickup is clearest when it states:','["only an apology", "no details", "a joke", "the order number, the new time and the location"]'::jsonb,3,'Include key facts.','original'),
('127.872.d.6.E',3,'A dock supervisor listens during the morning meeting, writes down the changes to the loading schedule and asks a question about door assignments. She is:','["practicing effective listening skills", "distracted listening", "ignoring directions", "interrupting"]'::jsonb,0,'Active listening includes notes and questions.','original'),
('127.872.d.6.E',4,'The best way to confirm that a caller''s complaint has been understood is to:','["end the call", "restate the complaint in your own words and ask if it is right", "say ''whatever''", "interrupt"]'::jsonb,1,'Paraphrase to confirm.','original'),
('127.872.d.6.F',3,'A student uses a warehouse manual to write step-by-step instructions for receiving a pallet. She is:','["copying jokes", "guessing steps", "employing writing and preparation skills with technical information", "skipping details"]'::jsonb,2,'Technical writing is precise.','original'),
('127.872.d.6.F',4,'A well-written receiving procedure should list steps:','["as a paragraph with no breaks", "in random order", "without warnings", "in the order they must be done, with safety warnings"]'::jsonb,3,'Order and warnings matter.','original'),
('127.872.d.6.G',3,'A student explains to the class how a pick-to-light system speeds up order filling, using a poster and a steady voice. He is demonstrating:','["speaking skills", "silence", "reading silently", "mumbling"]'::jsonb,0,'Present clearly.','original'),
('127.872.d.6.G',4,'To make a short technical talk more engaging, a speaker should:','["speak in a monotone", "use a visual aid and keep the key points brief", "avoid the audience", "read every word"]'::jsonb,1,'Visuals and brevity help.','original'),
('127.872.d.7.A',3,'A logistics firm funds work on faster sorting algorithms, better packaging materials and electric delivery vans. These are:','["decorations", "payroll tasks", "major fields of research and development", "unrelated hobbies"]'::jsonb,2,'R&D spans many fields.','original'),
('127.872.d.7.A',4,'Research and development in distribution tends to focus on:','["raising errors", "adding delays", "skipping safety", "lowering costs, speeding delivery and reducing waste"]'::jsonb,3,'R&D improves performance.','original'),
('127.872.d.7.B',3,'A team asks whether a new pallet-wrap pattern reduces load shifting, tests it on 20 shipments and compares results with the old pattern. They are:','["applying scientific methods of research", "guessing", "ignoring data", "copying"]'::jsonb,0,'Test, record, compare.','original'),
('127.872.d.7.B',4,'For a fair comparison of two packing methods, the team should:','["test once only", "use the same products and routes for both methods", "change many things", "use different products for each"]'::jsonb,1,'Control variables.','original'),
('127.872.d.7.C',3,'A student researching conveyor safety consults an equipment manual, a trade association report and a safety officer. She is:','["guessing", "using one source", "using a variety of resources for research and development", "using none"]'::jsonb,2,'Use varied sources.','original'),
('127.872.d.7.C',4,'The best source for current federal workplace safety data is:','["a rumor", "a social media comment", "an anonymous blog", "an official government agency such as OSHA"]'::jsonb,3,'Official sources are reliable.','original'),
('127.872.d.7.D',3,'A researcher states a hypothesis, designs a test, collects data, analyzes it and reports results. This sequence describes:','["the scientific method of research", "a sales pitch", "a guess", "a rumor"]'::jsonb,0,'Follow the method.','original'),
('127.872.d.7.D',4,'After testing, if the data does not support the hypothesis, a researcher should:','["ignore the result", "revise the hypothesis or design a new test", "change the data", "hide the data"]'::jsonb,1,'Science follows evidence.','original'),
('127.872.d.8.A',3,'A student proposes adding barcode scanners at the receiving dock, outlining the problem, cost and expected time savings for a manager. She is:','["ignoring costs", "avoiding ideas", "discussing a project proposal", "skipping planning"]'::jsonb,2,'Proposals outline problem, cost and benefit.','original'),
('127.872.d.8.A',4,'The part of a proposal that persuades decision makers by showing what the company gains is the:','["signature line", "page number", "title page only", "expected benefit"]'::jsonb,3,'Benefits justify cost.','original'),
('127.872.d.8.B',3,'A receiving clerk logs each shipment''s arrival time, carrier, count and condition in the warehouse system. This is:','["maintaining records appropriate to distribution and logistics", "skipping paperwork", "hiding data", "losing data"]'::jsonb,0,'Receiving records are required.','original'),
('127.872.d.8.B',4,'Accurate receiving records help a company to:','["hide shortages", "resolve damage claims and keep inventory correct", "skip counts", "avoid inspections"]'::jsonb,1,'Records support claims.','original'),
('127.872.d.8.C',3,'A planner records daily orders shipped for a month in a table and plots them on a line graph. She is:','["hiding numbers", "avoiding data", "collecting and organizing data in tables and graphs", "guessing"]'::jsonb,2,'Tables and graphs organize data.','original'),
('127.872.d.8.C',4,'Which chart type best shows the share of shipments by carrier?','["a blank page", "a map of the parking lot", "a paragraph only", "a pie chart"]'::jsonb,3,'Pie charts show parts of a whole.','original'),
('127.872.d.8.D',3,'A chart shows damaged shipments dropped from 12 to 4 per month after a new packing method. An analyst concludes:','["the new method likely reduced damage, though more data would confirm it", "nothing changed", "data is meaningless", "damage rose"]'::jsonb,0,'Interpret trends with caution.','original'),
('127.872.d.8.D',4,'A graph shows weekly orders of 500, 520, 510, 150 and 505. The 150 is best described as:','["an error to delete always", "an unusual value to investigate", "a typical week", "the average"]'::jsonb,1,'Check outliers.','original'),
('127.872.d.9.A',3,'A planner uses warehouse management software to assign storage locations, emails carriers pickup times and checks a port website for delays. These are:','["office furniture", "hand tools", "management, email and Internet applications in logistics", "unrelated tools"]'::jsonb,2,'Software supports operations.','original'),
('127.872.d.9.A',4,'A warehouse management system helps a facility to:','["increase misplaced items", "hide stock levels", "slow shipping", "track inventory locations and guide picking efficiently"]'::jsonb,3,'WMS tracks and directs.','original'),
('127.872.d.9.B',3,'A clerk writes a procedure, tracks stock counts in a spreadsheet, stores supplier details in a database and builds slides for a training. She is using:','["word-processing, database, spreadsheet and presentation software", "only a calculator", "no software", "only paper"]'::jsonb,0,'Office software types.','original'),
('127.872.d.9.B',4,'The best tool for storing thousands of customer records with searchable fields is a:','["word document", "database", "slide deck", "photo album"]'::jsonb,1,'Databases store and search records.','original'),
('127.872.d.9.C',3,'Teams in Dallas and Memphis review a shared inventory plan on a video call and edit the same file at once. These tools are:','["hand tools", "isolated tools", "collaborative, groupware and virtual meeting software", "paper tools"]'::jsonb,2,'Collaboration software connects teams.','original'),
('127.872.d.9.C',4,'Groupware helps a distribution team because it:','["blocks communication", "limits sharing", "prevents editing", "lets members share files and update plans together"]'::jsonb,3,'Groupware supports teamwork.','original'),
('127.872.d.9.D',3,'A fleet manager studies a map showing delivery clusters and uses satellite signals to track her trucks. These are:','["Geographic Information Systems and Global Positioning Systems", "hand drawings", "weather reports only", "guesswork"]'::jsonb,0,'GIS maps data; GPS locates vehicles.','original'),
('127.872.d.9.D',4,'A GIS is most useful to a logistics planner for:','["hiring a driver", "choosing warehouse locations near customers and good roads", "painting a sign", "naming a product"]'::jsonb,1,'GIS supports location decisions.','original'),
('127.872.d.9.E',3,'A distribution center uses handheld scanners, barcode printers and conveyor controls tied to its software. These are:','["hand tools only", "unrelated devices", "other computer-based equipment in distribution and logistics", "office furniture"]'::jsonb,2,'Scanners and controls are computer-based equipment.','original'),
('127.872.d.9.E',4,'Scanning a barcode at receiving helps a warehouse by:','["removing records", "slowing receiving", "adding errors", "recording the item automatically and reducing errors"]'::jsonb,3,'Scanning improves accuracy.','original'),
('127.872.d.10.A',3,'At the start of a shift, a warehouse team reviews the evacuation routes, the location of extinguishers and safe lifting methods. They are discussing:','["safe work practices and emergency procedures", "break schedules", "parking rules", "pay rates"]'::jsonb,0,'Safety briefings cover practices and emergencies.','original'),
('127.872.d.10.A',4,'If a fire alarm sounds in a warehouse, workers should first:','["wait for orders to ignore it", "stop work and follow the evacuation plan to the assembly point", "hide", "finish the task"]'::jsonb,1,'Evacuate promptly.','original'),
('127.872.d.10.B',3,'Rules from OSHA, such as requirements for forklift training and guarding, are examples of:','["marketing slogans", "rumors", "laws designed to promote safety and health in distribution workplaces", "optional tips"]'::jsonb,2,'OSHA sets workplace rules.','original'),
('127.872.d.10.B',4,'Under OSHA rules, employers must train forklift operators:','["after an accident", "never", "only once a decade", "before they operate the equipment"]'::jsonb,3,'Training must come first.','original'),
('127.872.d.10.C',3,'A trainee practices a pressure bandage on a mannequin arm and performs chest compressions on a manikin. He is demonstrating:','["first aid and CPR procedures", "cleaning", "office tasks", "parking"]'::jsonb,0,'Emergency response skills.','original'),
('127.872.d.10.C',4,'If a coworker collapses and does not respond or breathe normally, the first action is to:','["give a drink", "call 911 or direct someone to, and begin compressions if trained", "wait for a break", "leave the area"]'::jsonb,1,'Call and begin compressions.','original'),
('127.872.d.10.D',3,'A dock worker wears steel-toe boots, gloves and a high-visibility vest while loading trucks. She is demonstrating:','["ignoring rules", "unsafe dress", "proper use of safety equipment", "fashion choices"]'::jsonb,2,'Wear required PPE.','original'),
('127.872.d.10.D',4,'A back-support belt or proper lifting posture is used to help reduce the risk of:','["hearing loss", "sunburn", "eye damage", "strain injuries while moving heavy goods"]'::jsonb,3,'Lifting safely prevents strains.','original'),
('127.872.d.11.A',3,'A receiving team learns to stack boxes with heavy items on the bottom, keep fragile goods on top and use gloves with sharp edges. They are discussing:','["handling practices for goods and materials", "pay practices", "dress codes", "parking rules"]'::jsonb,0,'Handling affects damage and safety.','original'),
('127.872.d.11.A',4,'Goods marked ''this side up'' should be:','["turned over", "kept upright during handling and storage", "dropped", "stacked sideways"]'::jsonb,1,'Follow handling labels.','original'),
('127.872.d.11.B',3,'A shipper checks that a box''s dimensions and weight fit a carrier''s limits before sending it. She is explaining:','["color choices", "pay scales", "size, weight and shape requirements for packaging", "parking limits"]'::jsonb,2,'Carriers set size and weight rules.','original'),
('127.872.d.11.B',4,'A package that exceeds a carrier''s weight limit may be:','["sent faster", "ignored", "delivered free", "refused or charged extra fees"]'::jsonb,3,'Oversize costs more.','original'),
('127.872.d.11.C',3,'A shop chooses pallets and racks for storage, a forklift for moving goods and a parcel carrier for delivery. These are:','["material handling, storage and shipping methods", "decorating choices", "parking choices", "pay rates"]'::jsonb,0,'Methods for handling, storage and shipping.','original'),
('127.872.d.11.C',4,'Which shipping method is usually best for fast delivery of a small, urgent package?','["bulk rail", "express air freight", "slow barge", "hand cart"]'::jsonb,1,'Air is fastest.','original'),
('127.872.d.11.D',3,'A designer checks that the box is clear, readable and shows the barcode, the handling marks and the brand logo in the right places. She is:','["guessing", "avoiding labels", "analyzing visual design and appearance requirements for packages", "hiding information"]'::jsonb,2,'Packages must be readable and compliant.','original'),
('127.872.d.11.D',4,'An important appearance requirement for a package label is that it be:','["hidden", "small and faded", "covered by tape", "legible and placed where scanners can read it"]'::jsonb,3,'Legible labels prevent misrouting.','original'),
('127.872.d.11.E',3,'A supervisor sketches the path packages will take from the receiving dock through sorting, packing and shipping to reduce travel. She is discussing:','["layout plans for processing packages", "a vacation list", "a parking plan only", "a menu"]'::jsonb,0,'Layouts affect flow.','original'),
('127.872.d.11.E',4,'A good layout for a packing area should:','["block exits", "minimize backtracking and keep the work flowing in one direction", "maximize walking", "cross paths often"]'::jsonb,1,'Smooth flow saves time.','original')
